import numpy as np, glob
from datetime import datetime

def parse_time(val):
    if isinstance(val, np.ndarray): val = val.item()
    if isinstance(val, bytes): val = val.decode('utf-8')
    s = str(val)
    if s.endswith('Z'):
        s = s[:-1] + '+00:00'
    return datetime.fromisoformat(s)

vals=[]
for path in glob.glob('/root/data/*.npz'):
    with np.load(path, allow_pickle=True) as npz:
        et = npz['event_time']
        st = npz['start_time']
    t0 = (parse_time(et) - parse_time(st)).total_seconds()
    vals.append(t0)
print('t0 min', min(vals), 'max', max(vals), 'median', np.median(vals))
